-- Aide : le plan d'exécution (texte) d'une requête.
create function public.tap_explain(q text) returns text language plpgsql as $f$
declare r text; res text := '';
begin
  for r in execute 'explain ' || q loop res := res || r || E'
'; end loop;
  return res;
end $f$;

